P5E = {
 'malum.gui.book.entry.page.text.ritual_magic.1': 'В будущем таится много тайн…',
 # ---- ритуалы ----
 'malum.gui.book.entry.page.text.rite_of_ascension': 'Сложный ритуал: пока он активен, он плетёт связанный очаг ритуала. Проходя над блоками, очаг обращает их гравитацию вспять, заставляя подниматься на высоту до шестнадцати блоков.',
 'malum.gui.book.entry.page.text.rite_of_creation': 'Сложный ритуал: пока он активен, он плетёт связанный очаг ритуала. Проходя над пустотой, очаг превращает частицы воздуха в землю, образуя булыжник.',
 'malum.gui.book.entry.page.text.rite_of_culling': 'Сложный ритуал: пока он активен, он выбраковывает стада ближайших перенаселённых животных.',
 'malum.gui.book.entry.page.text.rite_of_destruction': 'Сложный ритуал: пока он активен, он плетёт связанный очаг ритуала. Проходя над блоками, очаг пытается их разрушить.',
 'malum.gui.book.entry.page.text.rite_of_empowerment': 'Простой ритуал: пока он активен, он усиливает души ближайших враждебных существ.',
 'malum.gui.book.entry.page.text.rite_of_gravity': 'Сложный ритуал: пока он активен, он плетёт связанный очаг ритуала. Проходя над блоками, очаг накладывает на них гравитацию, заставляя их падать.',
 'malum.gui.book.entry.page.text.rite_of_harming': 'Простой ритуал: пока он активен, он мало-помалу вредит душам ближайших существ.',
 'malum.gui.book.entry.page.text.rite_of_healing': 'Простой ритуал: пока он активен, он мало-помалу залечивает раны ближайших существ.',
 'malum.gui.book.entry.page.text.rite_of_lust': 'Сложный ритуал: пока он активен… ближайшие животные становятся… $iкрепкими/$, словно я накормил их сам.',
 'malum.gui.book.entry.page.text.rite_of_nourishment': 'Простой ритуал: пока он активен, он незаметно восстанавливает утраченную выносливость ближайших игроков, дольше сохраняя сытость.',
 'malum.gui.book.entry.page.text.rite_of_nurturing': 'Сложный ритуал: пока он активен, он накладывает на ближайших животных духовно взращивающий эффект, ускоряя рост и иные природные процессы.',
 'malum.gui.book.entry.page.text.rite_of_quickening': 'Сложный ритуал: пока он активен, он плетёт связанный очаг ритуала. Проходя над печами любого вида, очаг сильно ускоряет плавку.',
 'malum.gui.book.entry.page.text.rite_of_rending': 'Сложный ритуал: пока он активен, он бьёт уязвимых монстров, нанося смертельный удар и душе, и телу.',
 'malum.gui.book.entry.page.text.rite_of_sapping': 'Сложный ритуал: пока он активен, он плетёт связанный очаг ритуала. Проходя над котлами, очаг сильно ускоряет накопление жидкости из любого заострённого капельника сверху.',
 'malum.gui.book.entry.page.text.rite_of_smelting': 'Сложный ритуал: пока он активен, он плетёт связанный очаг ритуала. Проходя над блоками, очаг наполняет их огнём, мгновенно переплавляя, словно в печи.',
 'malum.gui.book.entry.page.text.rite_of_soaking': 'Сложный ритуал: пока он активен, он плетёт связанный очаг ритуала. Проходя над блоками, очаг накладывает эффект, ускоряющий рост, — подобно костной муке или просто ускоренному ходу времени.',
 'malum.gui.book.entry.page.text.rite_of_the_burning_fervor': 'Простой ритуал: пока он активен, он наделяет ближайших существ благословением «Пылающее рвение», повышая скорость атаки и скорость добычи.',
 'malum.gui.book.entry.page.text.rite_of_the_fiery_embrace': 'Простой ритуал: пока он активен, он тушит ближайших существ, а затем дарует им благословение «Огненные объятия», давая пассивное исцеление.',
 'malum.gui.book.entry.page.text.rite_of_the_flowing_grasp': 'Простой ритуал: пока он активен, он наделяет ближайших существ благословением «Текучая хватка», увеличивая радиус взаимодействия с блоками и расстояние подбора предметов.',
 'malum.gui.book.entry.page.text.rite_of_the_good_tides': 'Простой ритуал: пока он активен, он наделяет ближайших существ благословением «Благоприятные приливы», давая преимущества в один уровень от зачарований «Приманка» и «Морская удача».',
 'malum.gui.book.entry.page.text.rite_of_the_howling_gale': 'Простой ритуал: пока он активен, он наделяет ближайших существ благословением «Воющий шквал», повышая скорость передвижения и скорость атаки.',
 'malum.gui.book.entry.page.text.rite_of_the_oaken_might': 'Простой ритуал: пока он активен, он наделяет ближайших существ благословением «Дубовая мощь», давая прибавку к урону, которая удваивается с пустыми руками.',
 'malum.gui.book.entry.page.text.rite_of_the_sky_tether': 'Простой ритуал: пока он активен, он наделяет ближайших существ благословением «Небесный поводок», увеличивая высоту прыжка и уменьшая гравитацию, с умеренным снижением урона от падения.',
 'malum.gui.book.entry.page.text.rite_of_the_stone_ward': 'Простой ритуал: пока он активен, он наделяет ближайших существ благословением «Каменная защита», снижая получаемый урон — тем сильнее, чем меньше на вас брони.',
 # ---- руны ----
 'malum.gui.book.entry.page.text.rune_of_ailment_cleansing.1': 'Руна очищения от недугов побуждает тело к катализу и перемене вещества, позволяя быстрее обычного сжигать и перерабатывать отрицательные эффекты.',
 'malum.gui.book.entry.page.text.rune_of_burning_fervor.1': 'Руна пылающего рвения несёт эффект одноимённого ритуала: она наделяет носителя «Пылающим рвением» половинной силы, слегка повышая скорость атаки и скорость добычи.',
 'malum.gui.book.entry.page.text.rune_of_culling.1': 'Руна добивания побуждает разум искать гибель, даруя владельцу бонус к мастерству косы по раненым целям. Похоже, эффект включается на целях с половиной здоровья и ниже и повышает урон косы примерно на две пятых.',
 'malum.gui.book.entry.page.text.rune_of_dexterity.1': 'Руна ловкости побуждает разум двигаться, когда тот загнан в угол, повышая скорость передвижения; она может возрасти вдвое по мере того, как запас здоровья владельца тает.',
 'malum.gui.book.entry.page.text.rune_of_fiery_embrace.1': 'Руна огненных объятий несёт эффект одноимённого ритуала: когда носитель горит, она наделяет его «Огненными объятиями» половинной силы, тушит его и даёт пассивное исцеление.',
 'malum.gui.book.entry.page.text.rune_of_flowing_grasp.1': 'Руна текучей хватки несёт эффект одноимённого ритуала: она наделяет носителя «Текучей хваткой» половинной силы, слегка увеличивая радиус взаимодействия с блоками и расстояние подбора предметов.',
 'malum.gui.book.entry.page.text.rune_of_good_tides.1': 'Руна благоприятных приливов несёт эффект одноимённого ритуала: она наделяет носителя «Благоприятными приливами» половинной силы, давая преимущества в один уровень от зачарования «Приманка».',
 'malum.gui.book.entry.page.text.rune_of_howling_gale.1': 'Руна воющего шквала несёт эффект одноимённого ритуала: она наделяет носителя «Воющим шквалом» половинной силы, повышая скорость передвижения и скорость атаки.',
 'malum.gui.book.entry.page.text.rune_of_oaken_might.1': 'Руна дубовой мощи несёт эффект одноимённого ритуала: она наделяет носителя «Дубовой мощью» половинной силы, давая прибавку к урону, которая удваивается с пустыми руками.',
 'malum.gui.book.entry.page.text.rune_of_protection.1': 'Руна защиты побуждает тело стоять насмерть, даруя владельцу бонус к броне примерно в одну пятую.',
 'malum.gui.book.entry.page.text.rune_of_reinforcement.1': 'Руна подкрепления не побуждает тело, а просто давит на саму арканную природу его существования, увеличивая ёмкость и целостность оберега души.',
 'malum.gui.book.entry.page.text.rune_of_scorching.1': 'Руна опаления побуждает разум делиться своим светом с другими, невзирая на последствия: она удваивает силу урона огнём, исходящего от владельца.',
 'malum.gui.book.entry.page.text.rune_of_sky_tether.1': 'Руна небесного поводка несёт эффект одноимённого ритуала: она наделяет носителя «Небесным поводком» половинной силы, слегка увеличивая высоту прыжка и уменьшая гравитацию, с умеренным снижением урона от падения.',
 'malum.gui.book.entry.page.text.rune_of_stone_ward.1': 'Руна каменной защиты несёт эффект одноимённого ритуала: она наделяет носителя «Каменной защитой» половинной силы, давая небольшое снижение урона, которое усиливается, если на вас нет брони.',
 'malum.gui.book.entry.page.text.rune_of_vitality.1': 'Руна живучести побуждает тело восстанавливать само себя, усиливая всё получаемое исцеление примерно на одну пятую.',
 'malum.gui.book.entry.page.text.rune_of_volatile_distortion.1': 'Руна нестабильного искажения не побуждает разум, а искажает его действия случаем: урон атак владельца становится неровным — иногда, по воле случая, попадая в слабое место и удваивая силу атаки.',
 # ---- рунное дерево ----
 'malum.gui.book.entry.page.text.runewood.1': 'Рунное дерево — странная смесь магии и природы, и притом довольно обычная. Оно красиво, но меня больше занимает польза. Рунное дерево пропитано магией, а потому может служить основой для всего арканного.',
 'malum.gui.book.entry.page.text.runewood.2': 'Дерево встречается преимущественно на больших открытых равнинах, но попадается и в лесах. Проще всего его узнать по листве, что гордо являет оранжево-жёлтую палитру.',
 'malum.gui.book.entry.page.text.runewood.arcane_charcoal.1': 'Древесный уголь из рунного дерева, весь пропитанный магией, горит с арканным рвением дольше обычного угля. Он довольно полезен как топливо для любой плавки, какая мне ни понадобится.',
 'malum.gui.book.entry.page.text.runewood.runic_sap.1': 'На боках стволов рунного дерева нередко скапливается липкий сок. Когда это случается, снимите кору — и сок можно собрать в бутылку; из него выходит живительный напиток.',
 'malum.gui.book.entry.page.text.runewood.runic_sap.2': 'На вкус он отчасти напоминает мёд: сладкий, но с более земляным оттенком. Особенно примечательно послевкусие: оно живит в чистейшем виде, залечивая ваши раны.',
 'malum.gui.book.entry.page.text.runewood.runic_sap.3': 'Из сока также можно делать шарики сока: в большинстве рецептов они взаимозаменяемы с шариками слизи.',
 # ---- создание рун ----
 'malum.gui.book.entry.page.text.runeworking.1': 'Все аксессуары, что я создал доселе, нашли своё место в моей работе, но тратить время на выбор украшений перед каждым делом стало утомительно. В конце концов, быть может, иные эффекты можно отделить от их источника.',
 'malum.gui.book.entry.page.text.runeworking.2': 'Процесс создания рун позволяет мне сделать это с помощью брошей и рун. Брошь — просто избранный мной фокус; её положение над сердцем символизирует цену страдания, присущую рунической силе.',
 'malum.gui.book.entry.page.text.runeworking.3': 'Для начала мне понадобится создать рунический верстак, чтобы наносить эти руны. Простейшее начало — руническая брошь, которая позволит мне носить то, что я создал.',
 'malum.gui.book.entry.page.text.runic_brooch.1': 'Простейшая из брошей — руническая брошь. Она являет поиск силы за цену и окровавленные ладони, которыми хватают просветление на лезвии бритвы. При ношении она символически отнимает у одной руки способность проводить магию через кольцо и взамен даёт возможность начертить по руне в каждой ладони.',
 # ---- камень шрамов ----
 'malum.gui.book.entry.page.text.scarstone.1': 'Наблюдая за распространением порчи (в контролируемых условиях, разумеется), я обнаружил, что изредка метафизический шрам оказывается настолько силён, что задевает даже камень, — отсюда и название: камень шрамов.',
 'malum.gui.book.entry.page.text.scarstone.creation.1': 'Похоже, он появляется лишь случайно, и условий, необходимых для этого, мне выделить не удалось. Примерно каждый десятый раз, когда порча расползается, травма высекает залежи камня шрамов.',
 'malum.gui.book.entry.page.text.scarstone.material.1': 'Камень шрамов — порода странная, отчасти схожая с порчей. Я опознал в ней вкрапления гранита, обсидиана, диорита и андезита, а также более заурядного камня, без всякого порядка и смысла в узоре. Впрочем, для освобождённого ритуала он не резонирует.',
 'malum.gui.book.entry.page.text.scarstone.strange_crystal.1': 'Хотя с освобождённым ритуалом он не резонирует, в камне есть странное… обрастание? Он ведёт себя как растение, будучи кристаллом. Не знаю, что с этим делать. Будь я биомантом, это могло бы стать открытием всей жизни.',
 # ---- косы ----
 'malum.gui.book.entry.page.text.scythes.1': 'После нескольких безуспешных попыток я вставил камень душ в оружие, способное надёжно собирать эти кристаллы духов. Длинное лезвие даёт телу время умереть, прежде чем я ударю по душе, и вдобавок обеспечивает широкий размашистый удар. Оно не так остро, как меч, но для моих целей сгодится.',
 'malum.gui.book.entry.page.text.scythes.2': 'То, чего я добивался прежде осторожными, кропотливыми опытами, коса сделала за считанные секунды. Души убитых мной чудовищ раскололись, и ко мне потоком понеслись клочки глубоко окрашенной материи — кристаллы духов. Наконец-то моё исследование может начаться всерьёз.',
 'malum.gui.book.entry.page.text.scythes.enchanting.1': 'В основе своей коса зачаровывается так же, как прочее оружие и инструменты, что я использовал. Разумеется, из-за своей иной природы у неё собственный набор зачарований, но «Прочность» и тому подобное она принимает не хуже меча.',
 'malum.gui.book.entry.page.text.scythes.enchanting.animated.1': 'Если силу можно сосредоточить, её можно и рассеять. Любопытно: рассеяв силу, которая собиралась бы для «Преследуемого», по остальной косе, всё оружие обретает понятийную «лёгкость» — его взмахи становятся легче и быстрее.',
 'malum.gui.book.entry.page.text.scythes.enchanting.ascension.1': 'Занимательный символизм — роль орудия в возвышении человека. Цивилизацию выстроила пища, которую жнёт коса. Обратив назначение лезвия как орудия, я могу… ну, возвысить себя: ветры, на которых я поднимаюсь, будут остры, как само лезвие, для моих врагов. «Отскок» несовместим с ним — буквально идёт поперёк этого зачарования.',
 'malum.gui.book.entry.page.text.scythes.enchanting.haunted.1': 'Камень душ взаимодействует с душами — очевидно. Самое грубое и простое применение — удар тупой силой, разбивающий душу, как оконное стекло. Если я сгущу арканную силу камня, он станет бить и раскалывать сильнее, а может, и ранить тело отдачей.',
 'malum.gui.book.entry.page.text.scythes.enchanting.rebound.1': 'Коса жнёт. В этом её назначение, и его можно обратить себе на пользу. Нужна ли жнецу моя рука? Обратив назначение лезвия как оружия, я могу позволить ему отчасти действовать самому, словно бумеранг. Чем сильнее зачарование, тем скорее коса снова готова к броску.',
 'malum.gui.book.entry.page.text.scythes.enchanting.spirit_plunder.1': 'Метод не идеален: часть души неизбежно теряется в миг между лезвием и камнем. Но, зачаровав лезвие, эту потерю можно уменьшить и сгустить больше души. К сожалению, это напрягает камень и может привести к снижению прочности косы.',
}
